for cap in [29,32,35,36,38,43]:
 P=np.zeros_like(M)
 for y,x in zip(ys,xs):
  R=min(float(D[y,x]),cap);r=int(np.ceil(R));sl=(Y[45-r:46+r,45-r:46+r]**2+X[45-r:46+r,45-r:46+r]**2<=R**2)
  y0=max(0,y-r);y1=min(1024,y+r+1);x0=max(0,x-r);x1=min(1024,x+r+1);P[y0:y1,x0:x1]|=sl[y0-y+r:y1-y+r,x0-x+r:x1-x+r]
 inter=(P&M).sum(); union=(P|M).sum()
 def covgrid(nr,nc):
  yy,xx=np.where(M); a0,b0=yy.min(),xx.min(); a1,b1=yy.max()+1,xx.max()+1; vals=[]
  for i in range(nr):
   for j in range(nc):
